-- Athena saved query (Product_B2C_Intl)
-- ID: 66233995-6271-4327-acc4-f0e03541867e
-- Name: Bus Images Dashboard Current Coverage - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH sl_deduped AS ( SELECT __time, CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN os = 'iOS' AND app_code >= 859800 THEN mri_session_id END AS mri_session_id, route_id, os, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) > 2 THEN '3. DBD 2+' END AS dbd FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-05-28 18:30:00' AND __time < TIMESTAMP '2026-06-05 18:30:00' AND channel = 'MOBILE_APP' AND country = 'IND' AND status = 200 AND tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5, 6 UNION ALL SELECT __time, CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN os = 'Android' THEN mri_session_id END AS mri_session_id, route_id, os, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) > 2 THEN '3. DBD 2+' END AS dbd FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-05-28 18:30:00' AND __time < TIMESTAMP '2026-06-05 18:30:00' AND channel = 'MOBILE_APP' AND country = 'IND' AND status = 200 AND tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5, 6 ), base AS ( SELECT u.__time, CAST(DATE_TRUNC('day', at_timezone(u.__time, 'Asia/Kolkata')) AS DATE) AS doi, u.event_src channel, -- CASE WHEN CAST(doj_doi AS INT) <= 0 THEN '0. Same Day' -- WHEN CAST(doj_doi AS INT) = 1 THEN '1. DBD 1' -- WHEN CAST(doj_doi AS INT) = 2 THEN '2. DBD 2' -- WHEN CAST(doj_doi AS INT) = 3 THEN '3. DBD 2+' -- ELSE '' -- END AS DBD, u.route_id_train_no route_id, u.mri_session_id, MAX(CASE WHEN (CAST(DATE_TRUNC('day', at_timezone(u.__time, 'Asia/Kolkata')) AS DATE), u.route_id_train_no) IN ( SELECT DISTINCT CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, route_id_train_no FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-05-28 18:30:00' AND __time < TIMESTAMP '2026-06-05 18:30:00' AND event_src IN ('iOS') -- AND event_name IN ('ImagesSection_loaded') AND event_group IN ('ab_exp_busImage') AND event_name IN ('NewBusImageLoaded') ) AND u.event_src IN ('Android') AND u.event_group = 'sl_screen_load' AND u.event_name LIKE '%sl_loaded%' THEN 1 ELSE 0 END) AS NewBusImageEnabledSLLandOnAndroid, MAX(CASE WHEN u.event_group = 'sl_screen_load' AND u.event_name LIKE '%sl_loaded%' THEN 1 ELSE 0 END) AS overall_sl_loaded, -- MAX(CASE WHEN event_group = 'ab_exp_imagesSectionLoaded' AND event_name = 'ImagesSection_loaded' THEN 1 ELSE 0 END) AS ImagesSection_loaded, -- MAX(CASE WHEN event_group = 'ab_exp_imagesGalleryLoaded' AND event_name = 'ImagesGalleryLoaded' THEN 1 ELSE 0 END) AS SL_Load_with_Old_Bus_Images, MAX(CASE WHEN u.event_group = 'ab_exp_busImage' AND u.event_name = 'NewBusImageLoaded' THEN 1 ELSE 0 END) AS SL_Load_with_New_Bus_Images FROM "user_interaction"."ui_ux_events" u WHERE __time >= TIMESTAMP '2026-05-28 18:30:00' AND __time < TIMESTAMP '2026-06-05 18:30:00' AND event_src IN ('Android', 'iOS') -- AND event_name IN ('ImagesSection_loaded') AND event_group IN ('sl_screen_load', 'ab_exp_busImage', 'ab_exp_imagesGalleryLoaded', 'ab_exp_imagesSectionLoaded') AND (event_name IN ('NewBusImageLoaded') OR event_name LIKE '%sl_loaded%') GROUP BY 1, 2, 3, 4, 5 ) SELECT sl.doi, sl.os channel, sl.dbd DBD, COUNT(DISTINCT CASE WHEN b.overall_sl_loaded = 1 THEN sl.mri_session_id END) AS overall_sl_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 THEN sl.mri_session_id END) AS SL_Load_with_New_Bus_Images, COUNT(DISTINCT CASE WHEN b.NewBusImageEnabledSLLandOnAndroid = 1 THEN sl.mri_session_id END) AS NewBusImageEnabledSLLandOnAndroid FROM base b LEFT JOIN sl_deduped sl ON sl.mri_session_id = b.mri_session_id AND sl.route_id = CAST(b.route_id AS BIGINT) GROUP BY 1, 2, 3 ORDER BY 1, 2, 3 -- LIMIT 100
